layer.css:
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: sans-serif, ui-sans-serif, system-ui, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 15px; font-weight: 700; font-style: italic; line-height: 1.625; letter-spacing: normal; text-transform: lowercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: sans-serif, ui-sans-serif, system-ui, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 36px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: -0.9px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
